.ix .hero-stat b{font:800 1.5rem/1.1 var(--f-display);color:#fff;font-variant-numeric:tabular-nums}
[data-mode="dark"] .ix .hero-stat b{color:var(--side-fg)}
.ix .hero-stat span{font-size:.76rem;color:color-mix(in srgb,var(--side-fg) 72%,transparent)}
.ix .hero-stat.alert b{color:var(--accent)}
.ix .kpi .kico{position:absolute;right:14px;top:14px;width:34px;height:34px;border-radius:10px;display:grid;place-items:center;background:var(--brand-soft);color:var(--brand);z-index:1}
.ix .kpi .kico .ico{width:18px;height:18px}
