.ix .quick{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,190px),1fr));gap:10px}
.ix .qa{display:flex;align-items:center;gap:12px;padding:12px 14px;border:1px solid var(--line);border-radius:12px;background:var(--surface);cursor:pointer;text-align:left;transition:border-color .15s,transform .15s,box-shadow .15s;box-shadow:var(--shadow-sm);min-width:0}
.ix .qa:hover{border-color:var(--brand);transform:translateY(-2px);box-shadow:var(--shadow)}
