.ix .tgl span::after{content:"";position:absolute;top:2px;left:2px;width:16px;height:16px;border-radius:50%;background:#fff;box-shadow:0 1px 2px rgb(0 0 0 / .25);transition:transform .15s}
.ix .tgl input:checked+span{background:var(--ok)}
.ix .tgl input:checked+span::after{transform:translateX(16px)}
.ix .tgl input:focus-visible+span{outline:2px solid var(--brand);outline-offset:2px}
