.ix .rolecard{display:flex;gap:10px;align-items:center;padding:10px 12px;border:1px solid var(--line);border-radius:12px;background:var(--surface);cursor:pointer;text-align:left;transition:border-color .15s,background .15s}
.ix .rolecard:hover{border-color:var(--line-2)}
.ix .rolecard.on{border-color:var(--brand);background:var(--brand-soft)}
