.ix .pstats{display:flex;gap:16px;flex-wrap:wrap;font-size:.84rem;color:var(--muted)}
.ix .pstats b{color:var(--fg);font-size:1rem}
.ix .pgroup{display:flex;flex-direction:column;gap:6px}
.ix .pgroup h3{font-size:.72rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-top:4px}
.ix .prow{display:grid;grid-template-columns:32px minmax(0,1fr) auto;gap:10px;align-items:center;padding:8px 10px;border:1px solid var(--line);border-radius:10px}
.ix .prow .pi{width:30px;height:30px;border-radius:8px;background:var(--surface-2);display:grid;place-items:center;color:var(--muted)}
.ix .prow .pl{display:flex;flex-direction:column;min-width:0}
.ix .prow .pl b{font-size:.88rem}
.ix .prow .pl small{font-size:.72rem;color:var(--muted)}
.ix .pseg button{padding:5px 10px;font-size:.8rem}
.ix .pseg button.on.lv0{color:var(--muted)}
