@media (max-width:900px){.ix .roles-grid{grid-template-columns:minmax(0,1fr)}
.ix .rolelist{position:static;flex-direction:row;overflow-x:auto;padding-bottom:4px}
.ix .rolecard{min-width:200px}}
@media (max-width:520px){.ix .prow{grid-template-columns:30px minmax(0,1fr)}
