@media (prefers-reduced-motion:reduce){.ix, .ix *,.ix *::before,.ix *::after{transition:none!important;animation:none!important}}
/* integración con el portal: tipografía, colores y capas */
.ix{--f-display:var(--fh);--f-body:var(--ff);background:transparent;font-size:15px;line-height:1.55;color:var(--fg)}
.ix.ix-page{min-height:0}
.ix-layer{position:relative;z-index:1000}
.ix #ixmodal .mback{z-index:1000}
.ix .modal{max-width:none;width:auto;margin:0;box-shadow:var(--shadow);animation:none}
.ix .head{display:none}
.ix-page>.tabs:first-child,.ix-page>.alert:first-child{margin-top:0}
.ix-page{display:flex;flex-direction:column;gap:16px}

</style>
<style>
:root{
  /* Valores base (tema Institucional); el tema activo los reemplaza desde el panel */
  --navy:#0a2a5e; --navy2:#0d3a80; --blue:#1556b8; --blue2:#1f6fd6; --sky:#e8f0fc; --blue-rgb:21,86,184; --ov:7,30,72;
  --gold:#f2b705; --gold2:#ffcb2d; --hc:#0a2a5e; --link:#1556b8;
  --page:#fff; --card:#fff; --card2:#f6f9fd; --bg:#f4f7fb; --bg2:#eff3f9; --white:#fff;
  --ink:#1b2433; --ink2:#4a5568; --muted:#5f6b7c; --line:#dfe5ee; --line2:#c9d5e6;
  --ok:#18794a; --okbg:#e3f5ea; --okink:#0f5a31; --warn:#955800; --warnbg:#fff3dc; --warnink:#6b4200;
  --err:#c62828; --errbg:#fde8e8; --errink:#7a1414; --info:#1556b8; --infobg:#e8f0fc; --infoink:#0b3a7e;
  --violet:#5b3cc4; --violetbg:#efeafd; --graybg:#eef0f3; --grayink:#55606e;
  --r:12px; --sh:0 1px 2px rgba(var(--ov),.06),0 4px 14px rgba(var(--ov),.07); --sh2:0 10px 34px rgba(var(--ov),.18);
  --ff:"Inter",system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
  --fh:"Montserrat","Inter",system-ui,"Segoe UI",Arial,sans-serif;
  --pattern:radial-gradient(rgba(255,255,255,.09) 1.2px,transparent 1.3px);
  color-scheme:light;
}
/* Tema 2: Esmeralda (verde y ámbar) */
/* Modo oscuro: superficies y textos neutros (los colores de marca los define el tema activo) */
:root[data-mode="dark"]{
  --page:#0b1220; --card:#121c32; --card2:#16223b; --bg:#0e1729; --bg2:#0b1324; --white:#121c32;
  --ink:#e4e9f2; --ink2:#b4bfd3; --muted:#8e9ab0; --line:#24324e; --line2:#33456a;
  --ok:#3cc47f; --okbg:#10301f; --okink:#a8f0c8; --warn:#f2a93b; --warnbg:#33240c; --warnink:#fcd9a0;
  --err:#ff6b6b; --errbg:#3a1519; --errink:#ffc4c4; --info:#4c8dff; --infobg:#14264a; --infoink:#c3d8ff;
  --violet:#a08cf7; --violetbg:#251e47; --graybg:#222c40; --grayink:#b4bfd3;
  --sh:0 1px 2px rgba(0,0,0,.4),0 4px 14px rgba(0,0,0,.3); --sh2:0 12px 34px rgba(0,0,0,.55);
  color-scheme:dark;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--ff);color:var(--ink);background:var(--page);font-size:15px;line-height:1.6;overflow-x:hidden}
img{max-width:100%;display:block}
a{color:var(--link)}
a:hover{color:var(--navy2)}
h1,h2,h3,h4{font-family:var(--fh);line-height:1.25;color:var(--hc);margin:0 0 .5em}
p{margin:0 0 1em}
button,input,select,textarea{font:inherit}
:focus-visible{outline:3px solid var(--gold);outline-offset:2px}
.sr-only{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.skip{position:absolute;left:-999px;top:0;background:var(--gold);color:#000;padding:8px 14px;z-index:999;font-weight:700}
.skip:focus{left:8px}
.wrap{max-width:1240px;margin:0 auto;padding:0 16px}
.proto-ribbon{background:#111827;color:#fde68a;font-size:12px;text-align:center;padding:4px 12px}
.proto-ribbon a{color:#fff;font-weight:600}

/* ===== Top bar / header ===== */
.topbar{background:var(--navy);color:rgba(255,255,255,.85);font-size:13px}
.topbar .wrap{display:flex;gap:18px;align-items:center;justify-content:space-between;min-height:36px;flex-wrap:wrap}
.topbar a{color:rgba(255,255,255,.85);text-decoration:none}
.topbar a:hover{color:#fff}
.topbar .tb-links{display:flex;gap:16px;flex-wrap:wrap;align-items:center}
.topbar .tb-links span,.topbar .tb-links a{display:inline-flex;gap:6px;align-items:center}
.social{display:flex;gap:6px}
.social a{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.12)}
.social a:hover{background:var(--gold)}
.social svg{width:14px;height:14px;fill:#fff}
.home-announcement{margin:0;padding:12px 16px;background:#ffdf58;color:#1f2937;text-align:center;font-size:16px;font-weight:700;line-height:1.5;overflow-wrap:break-word}
.site-header{background:var(--card);border-bottom:1px solid var(--line)}
.site-header .wrap{display:flex;align-items:center;gap:18px;padding-top:10px;padding-bottom:10px}
.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--hc);min-width:0}
.brand img{width:64px;height:64px}
.brand strong{font-family:var(--fh);font-size:26px;letter-spacing:.3px;display:block;line-height:1.05}
.brand small{display:block;color:var(--ink2);font-size:13px;line-height:1.3}
.brand em{display:block;color:var(--link);font-size:12.5px}
.h-search{margin-left:auto;display:flex;max-width:320px;flex:1}
.h-search input{flex:1;border:1px solid var(--line);border-radius:8px 0 0 8px;padding:9px 12px;min-width:0}
.h-search button{border:0;background:var(--navy2);color:#fff;border-radius:0 8px 8px 0;padding:0 14px;cursor:pointer}
.h-slogan{font-family:var(--fh);font-style:italic;color:var(--link);font-size:14px;line-height:1.25;max-width:140px;border-left:3px solid var(--gold);padding-left:10px}
.menu-btn{display:none;border:0;background:var(--navy2);color:#fff;border-radius:8px;padding:9px 12px;cursor:pointer;margin-left:auto}

/* ===== Main nav ===== */
.mainnav{background:linear-gradient(90deg,var(--navy2),var(--blue));position:sticky;top:0;z-index:50;box-shadow:0 2px 8px rgba(0,0,0,.15)}
.mainnav>.wrap>ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap}
.mainnav li{position:relative}
.mainnav .top{display:flex;align-items:center;gap:6px;color:#fff;text-decoration:none;padding:13px 16px;font-weight:600;font-size:14.5px;background:none;border:0;cursor:pointer;white-space:nowrap}
.mainnav .top:hover,.mainnav li:focus-within>.top,.mainnav .top.active{background:rgba(255,255,255,.14)}
.mainnav .top.active{box-shadow:inset 0 -3px 0 var(--gold)}
.mainnav .home{background:var(--blue2)}
.sub{position:absolute;left:0;top:100%;background:var(--card);min-width:260px;list-style:none;margin:0;padding:6px 0;border-radius:0 0 10px 10px;box-shadow:var(--sh2);display:none;z-index:60}
.mainnav li:hover>.sub,.mainnav li:focus-within>.sub,.mainnav li.open>.sub{display:block}
.sub a{display:flex;gap:8px;align-items:center;padding:9px 16px;color:var(--ink);text-decoration:none;font-size:14px}
.sub a:hover,.sub a:focus{background:var(--sky);color:var(--hc)}
.sub .ext::after{content:"↗";margin-left:auto;color:var(--muted);font-size:12px}

/* ===== Hero / banner ===== */
.page-banner{position:relative;color:#fff;min-height:170px;display:flex;align-items:center;overflow:hidden;background:var(--navy)}
.page-banner img.bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.9}
.page-banner::before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(var(--ov),.92) 0%,rgba(var(--ov),.65) 45%,rgba(var(--ov),.05) 100%);z-index:1}
.page-banner .wrap{position:relative;z-index:2;width:100%}
.page-banner .kicker{text-transform:uppercase;font-size:13px;letter-spacing:1.5px;color:rgba(255,255,255,.8);font-weight:600}
.page-banner .ttl{font-family:var(--fh);font-size:40px;font-weight:800;color:#fff;margin:2px 0;line-height:1.1}
.page-banner p{margin:0;font-size:17px;max-width:560px}
.crumbs{background:var(--card);border-bottom:1px solid var(--line);font-size:13.5px}
.crumbs ol{list-style:none;display:flex;flex-wrap:wrap;gap:6px;margin:0;padding:10px 0}
.crumbs li+li::before{content:"›";margin-right:6px;color:var(--muted)}
.crumbs a{text-decoration:none;color:var(--link)}
.crumbs [aria-current]{font-weight:600;color:var(--hc)}

/* ===== Layout ===== */
.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:28px;padding:28px 16px 44px}
.layout.left{grid-template-columns:260px minmax(0,1fr)}
.layout.full{grid-template-columns:minmax(0,1fr)}
.content h1{font-size:30px;position:relative;padding-bottom:10px;margin-bottom:16px}
.content h1::after{content:"";position:absolute;left:0;bottom:0;width:64px;height:4px;border-radius:2px;background:var(--gold)}
.content h2{font-size:22px;margin-top:1.2em}
.content h3{font-size:18px}
.lead{font-size:16.5px;color:var(--ink2)}
.side-box{background:var(--card);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;margin-bottom:18px;box-shadow:var(--sh)}
.side-box h2{font-size:16px;margin:0;background:var(--navy2);color:#fff;padding:12px 16px;display:flex;gap:8px;align-items:center}
.side-box ul{list-style:none;margin:0;padding:6px 0}
.side-box li a{display:flex;align-items:center;gap:8px;padding:9px 16px;text-decoration:none;color:var(--ink);font-size:14px;border-left:3px solid transparent}
.side-box li a::before{content:"›";color:var(--link);font-weight:700}
.side-box li a:hover{background:var(--sky)}
.side-box li a[aria-current]{background:var(--sky);border-left-color:var(--link);font-weight:700;color:var(--hc)}
.side-box .pad{padding:14px 16px;font-size:14px}
.promo{border-radius:var(--r);background:linear-gradient(135deg,var(--navy2),var(--blue2));color:#fff;padding:20px;margin-bottom:18px}
.promo q,.promo blockquote{font-style:italic;margin:0;font-size:15px}
.promo strong{display:block;font-family:var(--fh);font-size:18px}

/* ===== Generic components ===== */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid transparent;border-radius:8px;padding:9px 16px;font-weight:600;font-size:14px;cursor:pointer;text-decoration:none;line-height:1.2;background:var(--blue);color:#fff;transition:.15s}
.btn:hover{background:var(--navy2);color:#fff}
.btn.sec{background:var(--card);color:var(--link);border-color:var(--line2)}
.btn.sec:hover{background:var(--sky)}
.btn.gold{background:var(--gold);color:#1b1b1b}
.btn.gold:hover{background:var(--gold2)}
.btn.ok{background:var(--ok)}
.btn.danger{background:var(--err)}
.btn.ghost{background:transparent;color:var(--ink2);border-color:var(--line)}
.btn.ghost:hover{background:var(--bg);color:var(--ink)}
.btn.sm{padding:6px 10px;font-size:13px}
.btn.xs{padding:4px 8px;font-size:12px;border-radius:6px}
.btn[disabled]{opacity:.5;cursor:not-allowed}
.btn.violet{background:var(--violet)}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh)}
.card .cb{padding:18px}
.grid{display:grid;gap:18px}
.g2{grid-template-columns:repeat(2,minmax(0,1fr))}
.g3{grid-template-columns:repeat(3,minmax(0,1fr))}
.g4{grid-template-columns:repeat(4,minmax(0,1fr))}
.badge{display:inline-block;padding:2px 9px;border-radius:999px;font-size:12px;font-weight:600;background:var(--sky);color:var(--link);white-space:nowrap}
.badge.ok{background:var(--okbg);color:var(--ok)}
.badge.warn{background:var(--warnbg);color:var(--warn)}
.badge.err{background:var(--errbg);color:var(--err)}
.badge.gray{background:var(--graybg);color:var(--grayink)}
.badge.violet{background:var(--violetbg);color:var(--violet)}
.notice{border-radius:var(--r);padding:12px 16px;background:var(--infobg);color:var(--infoink);border-left:4px solid var(--blue);margin:12px 0;font-size:14.5px}
.notice.warn{background:var(--warnbg);border-color:var(--warn);color:var(--warnink)}
.notice.ok{background:var(--okbg);border-color:var(--ok);color:var(--okink)}
.notice.err{background:var(--errbg);border-color:var(--err);color:var(--errink)}
.empty{text-align:center;padding:30px 16px;color:var(--muted);background:var(--bg);border:1px dashed var(--line);border-radius:var(--r)}
.quote{border-left:4px solid var(--gold);background:var(--bg);padding:14px 18px;border-radius:0 var(--r) var(--r) 0;font-style:italic;color:var(--hc)}
.figure{margin:0 0 18px}
.figure img{width:100%;border-radius:var(--r);aspect-ratio:16/9;object-fit:cover}
.figure figcaption{font-size:13px;color:var(--muted);margin-top:6px;text-align:center}
.float-img{float:left;width:44%;margin:0 22px 12px 0}
.prose ul,.prose ol{padding-left:22px}
.prose img{border-radius:8px;margin:10px 0}
.clear{clear:both}

/* tables */
.tbl-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:var(--r);background:var(--card)}
table.tbl{width:100%;border-collapse:collapse;font-size:14px}
.tbl th{background:var(--navy2);color:#fff;text-align:left;padding:10px 12px;font-weight:600;white-space:nowrap}
.tbl td{padding:9px 12px;border-top:1px solid var(--line);vertical-align:middle}
.tbl tbody tr:nth-child(even){background:var(--card2)}
.tbl tbody tr:hover{background:var(--sky)}
.tbl .num{text-align:right;font-variant-numeric:tabular-nums}
.tbl .c{text-align:center}
.tbl.light th{background:var(--card2);color:var(--hc)}
.tbl caption{caption-side:top;text-align:left;font-weight:700;color:var(--hc);padding:0 0 8px}

/* forms */
.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 18px}
.form-grid .full{grid-column:1/-1}
.field label,.lbl{display:block;font-weight:600;font-size:13.5px;margin-bottom:5px;color:var(--ink)}
.req{color:var(--err)}
.field input,.field select,.field textarea,.inp{width:100%;border:1px solid var(--line2);border-radius:8px;padding:9px 12px;background:var(--card);color:var(--ink)}
.field textarea{min-height:110px;resize:vertical}
.field input:focus,.field select:focus,.field textarea:focus,.inp:focus{border-color:var(--link);outline:2px solid rgba(var(--blue-rgb),.22)}
.field .hint{font-size:12px;color:var(--muted);margin-top:4px}
.field.invalid input,.field.invalid select,.field.invalid textarea,.field.invalid .rte{border-color:var(--err);background:var(--errbg)}
.field .errmsg{color:var(--err);font-size:12.5px;margin-top:4px}
.check{display:flex;gap:9px;align-items:flex-start;font-size:14px}
.check input{margin-top:4px;width:16px;height:16px}
.captcha{display:flex;gap:10px;align-items:center;background:var(--bg);border:1px solid var(--line);padding:10px 12px;border-radius:8px;flex-wrap:wrap}
.captcha b{font-family:var(--fh);font-size:17px;letter-spacing:2px;background:var(--card);border:1px dashed var(--line2);padding:3px 10px;border-radius:6px;user-select:none}
.captcha input{width:90px}
.hp{position:absolute;left:-5000px}
.filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;align-items:end;background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:14px;margin-bottom:14px}
.filters .actions{display:flex;gap:8px}
.pager{display:flex;gap:6px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-top:12px;font-size:13.5px}
.pager .pages{display:flex;gap:4px;flex-wrap:wrap}
.pager button{border:1px solid var(--line);background:var(--card);border-radius:6px;min-width:34px;height:32px;cursor:pointer}
.pager button[aria-current]{background:var(--blue);color:#fff;border-color:var(--link)}
.pager select{border:1px solid var(--line);border-radius:6px;padding:4px}
.tabs{display:flex;gap:4px;border-bottom:2px solid var(--line);margin-bottom:16px;flex-wrap:wrap}
.tabs button{border:0;background:none;padding:10px 14px;cursor:pointer;font-weight:600;color:var(--ink2);border-bottom:3px solid transparent;margin-bottom:-2px}
.tabs button[aria-selected=true]{color:var(--link);border-bottom-color:var(--link)}
.chips{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}
.chip{border:1px solid var(--line2);background:var(--card);color:var(--hc);padding:6px 14px;border-radius:999px;cursor:pointer;font-size:13.5px;font-weight:600}
.chip[aria-pressed=true],.chip[aria-current=true]{background:var(--blue);color:#fff;border-color:var(--link)}

/* ===== Home ===== */
.hero{position:relative;height:460px;overflow:hidden;background:var(--navy)}
.slide{position:absolute;inset:0;opacity:0;transition:opacity .7s;visibility:hidden}
.slide.on{opacity:1;visibility:visible}
.slide img{width:100%;height:100%;object-fit:cover}
.slide::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(var(--ov),.9),rgba(var(--ov),.45) 55%,rgba(var(--ov),0))}
.slide .cap{position:absolute;z-index:2;inset:0;display:flex;align-items:center}
.slide .cap .wrap{width:100%}
.slide .cap h2{color:#fff;font-size:44px;max-width:620px;font-weight:800}
.slide .cap p{color:rgba(255,255,255,.92);font-size:18px;max-width:520px}
.hero-dots{position:absolute;z-index:3;bottom:18px;left:50%;transform:translateX(-50%);display:flex;gap:8px}
.hero-dots button{width:12px;height:12px;border-radius:50%;border:2px solid #fff;background:transparent;cursor:pointer;padding:0}
.hero-dots button[aria-current=true]{background:var(--gold);border-color:var(--gold)}
.hero-arrow{position:absolute;z-index:3;top:50%;transform:translateY(-50%);background:rgba(255,255,255,.18);color:#fff;border:0;width:42px;height:42px;border-radius:50%;cursor:pointer;font-size:20px}
.hero-arrow:hover{background:rgba(255,255,255,.35)}
.hero-arrow.l{left:14px}.hero-arrow.r{right:14px}
.quick{margin-top:-46px;position:relative;z-index:5}
.quick a{display:flex;gap:14px;align-items:center;background:var(--card);border-radius:var(--r);padding:18px;box-shadow:var(--sh2);text-decoration:none;color:var(--ink);border-bottom:4px solid var(--gold);transition:.2s}
.quick a:hover{transform:translateY(-3px)}
.quick .ic{width:50px;height:50px;border-radius:12px;background:var(--sky);display:grid;place-items:center;flex:none}
.quick .ic svg{width:26px;height:26px;stroke:var(--link);fill:none;stroke-width:2}
.quick strong{display:block;color:var(--hc);font-family:var(--fh)}
.quick small{color:var(--muted)}
section.sec{padding:56px 0}
section.sec.alt{background:var(--bg)}
.sec-h{text-align:center;max-width:720px;margin:0 auto 32px}
.sec-h .kicker{color:var(--link);font-weight:700;text-transform:uppercase;letter-spacing:1.5px;font-size:13px}
.sec-h h2{font-size:32px;margin:.2em 0}
.sec-h p{color:var(--ink2)}
.welcome{display:grid;grid-template-columns:320px 1fr;gap:36px;align-items:center}
.welcome img{border-radius:14px;box-shadow:var(--sh2);aspect-ratio:4/5;object-fit:cover;width:100%}
.stats{background:linear-gradient(120deg,var(--navy),var(--blue));color:#fff}
.stat{text-align:center;padding:10px}
.stat b{font-family:var(--fh);font-size:42px;display:block;color:var(--gold);line-height:1.1}
.stat span{font-weight:600}
.stat small{display:block;color:rgba(255,255,255,.72);font-size:12px}
.pcard{display:flex;flex-direction:column;overflow:hidden;text-decoration:none;color:var(--ink);transition:.2s;height:100%}
.pcard:hover{transform:translateY(-4px);box-shadow:var(--sh2)}
.pcard img{aspect-ratio:16/10;object-fit:cover;width:100%}
.pcard .cb{display:flex;flex-direction:column;flex:1}
.pcard h3{font-size:16.5px}
.pcard p{font-size:14px;color:var(--ink2);flex:1}
.pcard .more{color:var(--link);font-weight:700;font-size:14px}
.ncard{overflow:hidden;display:flex;flex-direction:column;height:100%}
.ncard .img{position:relative}
.ncard img{aspect-ratio:16/10;object-fit:cover;width:100%}
.ncard .img .badge{position:absolute;left:10px;top:10px;background:var(--gold);color:#111}
.ncard .cb{flex:1;display:flex;flex-direction:column}
.ncard .meta{font-size:12.5px;color:var(--muted);display:flex;gap:10px;flex-wrap:wrap;margin-bottom:4px}
.ncard h3{font-size:16px;margin-bottom:6px}
.ncard h3 a{color:var(--hc);text-decoration:none}
.ncard p{font-size:14px;color:var(--ink2);flex:1}
.ncard .more{font-weight:700;font-size:14px;text-decoration:none}
.benefit{display:flex;gap:14px;align-items:flex-start;padding:18px}
.benefit .ic{width:46px;height:46px;border-radius:50%;background:var(--navy2);display:grid;place-items:center;flex:none}
.benefit .ic svg{width:22px;height:22px;stroke:var(--gold);fill:none;stroke-width:2}
.benefit h3{font-size:15.5px;margin:0 0 4px}
.benefit p{font-size:13.5px;color:var(--ink2);margin:0}
.people-strip{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:16px}
.person{text-align:center}
.person img{aspect-ratio:1;object-fit:cover;border-radius:12px;width:100%;background:var(--sky)}
.person strong{display:block;color:var(--hc);font-size:14.5px;margin-top:8px;line-height:1.3}
.person small{color:var(--muted);font-size:12.5px}
.testi{padding:22px}
.testi blockquote{margin:0 0 14px;font-style:italic;color:var(--ink2)}
.testi .who{display:flex;gap:12px;align-items:center}
.testi .who img{width:52px;height:52px;border-radius:50%;object-fit:cover}
.event{display:flex;gap:14px;padding:14px}
.event .d{background:var(--navy2);color:#fff;border-radius:10px;min-width:64px;text-align:center;padding:8px 6px;font-family:var(--fh);line-height:1.1}
.event .d b{display:block;font-size:24px;color:var(--gold)}
.event .d small{font-size:12px;text-transform:uppercase}
.event h3{font-size:15.5px;margin:0 0 3px}
.event p{font-size:13.5px;margin:0;color:var(--ink2)}
.minedu-links{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}
.minedu-links a{display:flex;align-items:center;gap:12px;padding:16px;background:var(--card);border:1px solid var(--line);border-radius:var(--r);text-decoration:none;color:var(--hc);font-weight:700;font-family:var(--fh)}
.minedu-links a:hover{border-color:var(--link);box-shadow:var(--sh)}
.minedu-links .lg{width:44px;height:44px;border-radius:10px;display:grid;place-items:center;color:#fff;font-size:13px;flex:none}

/* ===== Plana ===== */
.director{display:grid;grid-template-columns:260px 1fr;gap:0;background:linear-gradient(135deg,var(--navy),var(--navy2));color:#fff;border-radius:14px;overflow:hidden;margin-bottom:22px}
.director img{width:100%;height:100%;object-fit:cover;min-height:280px}
.director .msg{padding:26px}
.director .msg blockquote{margin:0 0 16px;font-size:16px;font-style:italic;color:rgba(255,255,255,.92)}
.director .msg strong{display:block;font-family:var(--fh);font-size:20px;color:#fff}
.director .msg span{color:var(--gold);font-weight:600}
.collage{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:16px}
.collage figure{margin:0;background:var(--card);border:1px solid var(--line);border-radius:12px;overflow:hidden;box-shadow:var(--sh)}
.collage img{aspect-ratio:4/5;object-fit:cover;width:100%;background:var(--sky)}
.collage figcaption{padding:10px 12px;text-align:center}
.collage figcaption strong{display:block;color:var(--hc);font-size:14px;line-height:1.3}
.collage figcaption small{color:var(--muted);font-size:12.5px;display:block}
.cat-tabs{display:grid;grid-template-columns:repeat(auto-fit,minmax(104px,1fr));gap:8px;margin-bottom:18px}
.cat-tabs button{border:1px solid var(--line);background:var(--card);border-radius:10px;padding:10px 6px;font-size:12px;font-weight:600;color:var(--hc);cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:6px;line-height:1.25;text-align:center}
.cat-tabs button svg{width:24px;height:24px;stroke:currentColor;fill:none;stroke-width:1.8}
.cat-tabs button[aria-pressed=true]{background:var(--navy2);color:#fff;border-color:var(--navy2)}
.tcard{text-align:center;overflow:hidden;display:flex;flex-direction:column}
.tcard img{aspect-ratio:1;object-fit:cover;width:100%;background:var(--sky)}
.tcard .cb{padding:12px;flex:1;display:flex;flex-direction:column;gap:4px}
.tcard strong{color:var(--hc);font-size:14px;line-height:1.3}
.tcard small{color:var(--muted);font-size:12.5px}
.tcard .btn{margin-top:auto}

/* ===== Program page ===== */
.prog-hero{position:relative;background:var(--navy);color:#fff;overflow:hidden}
.prog-hero img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.55}
.prog-hero .wrap{position:relative;padding-top:38px;padding-bottom:38px}
.prog-hero .ttl{font-family:var(--fh);font-weight:800;font-size:34px;color:#fff;max-width:820px;line-height:1.15;margin:4px 0}
.prog-facts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr)) auto;gap:0;background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh2);margin-top:-26px;position:relative;z-index:3}
.prog-facts>div{padding:14px 16px;border-right:1px solid var(--line);display:flex;gap:10px;align-items:center}
.prog-facts svg{width:28px;height:28px;stroke:var(--link);fill:none;stroke-width:1.8;flex:none}
.prog-facts small{display:block;color:var(--muted);font-size:12px}
.prog-facts b{color:var(--hc);font-size:14.5px}
.prog-facts .cta{border:0;justify-content:center}
.block{margin-bottom:26px}
.block>h2{display:flex;gap:10px;align-items:center;font-size:20px;margin-top:0}
.block>h2 svg{width:24px;height:24px;stroke:var(--link);fill:none;stroke-width:2}
.dl-card{display:flex;gap:14px;align-items:center;padding:16px}
.dl-card .ft{width:46px;height:54px;border-radius:6px;display:grid;place-items:center;color:#fff;font-weight:800;font-size:12px;flex:none}
.dl-card h3{font-size:15px;margin:0 0 2px}
.dl-card p{margin:0 0 6px;font-size:13px;color:var(--ink2)}
.mod{border:1px solid var(--line);border-radius:var(--r);margin-bottom:10px;overflow:hidden;background:var(--card)}
.mod summary{cursor:pointer;padding:12px 16px;font-weight:700;color:var(--hc);background:var(--card2);list-style:none;display:flex;justify-content:space-between;gap:10px}
.mod summary::after{content:"+";font-size:18px;color:var(--link)}
.mod[open] summary::after{content:"–"}
.fields-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px}
.fields-list li{list-style:none;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 14px;display:flex;gap:10px;align-items:center;font-size:14px}
.fields-list li::before{content:"";width:10px;height:10px;border-radius:50%;background:var(--gold);flex:none}
.fields-list{padding:0;margin:0}

/* ===== Footer ===== */
.site-footer{background:var(--navy);color:rgba(255,255,255,.78);font-size:14px;margin-top:0}
.site-footer .wrap{display:grid;grid-template-columns:1.4fr 1fr 1.3fr 1fr;gap:28px;padding-top:36px;padding-bottom:26px}
.site-footer h2{color:#fff;font-size:15px;margin-bottom:12px}
.site-footer a{color:rgba(255,255,255,.78);text-decoration:none}
.site-footer a:hover{color:#fff;text-decoration:underline}
.site-footer ul{list-style:none;margin:0;padding:0}
.site-footer li{margin-bottom:6px}
.site-footer address{font-style:normal}
.site-footer address div{display:flex;gap:8px;margin-bottom:6px}
.f-brand{display:flex;gap:12px;align-items:center;margin-bottom:12px}
.f-brand img{width:58px;height:58px}
.f-brand strong{color:#fff;font-family:var(--fh);font-size:19px;display:block}
.f-logos{display:flex;gap:10px;margin-top:14px;flex-wrap:wrap}
.f-logos a{background:var(--card);border-radius:8px;padding:6px 10px;color:var(--hc);font-weight:800;font-size:12px;font-family:var(--fh)}
.f-bottom{border-top:1px solid rgba(255,255,255,.12);font-size:13px}
.f-bottom .wrap{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding-top:12px;padding-bottom:12px;grid-template-columns:none}
.f-bottom nav{display:flex;gap:16px;flex-wrap:wrap}
.newsletter{display:flex;margin-top:10px}
.newsletter input{flex:1;border:0;border-radius:8px 0 0 8px;padding:8px 10px;min-width:0}
.newsletter button{border:0;border-radius:0 8px 8px 0;background:var(--gold);padding:0 12px;font-weight:700;cursor:pointer}

/* WhatsApp & popup & modal */
.wa{position:fixed;right:18px;bottom:18px;z-index:80;width:56px;height:56px;border-radius:50%;background:#25d366;display:grid;place-items:center;box-shadow:0 6px 18px rgba(0,0,0,.25)}
.wa svg{width:30px;height:30px;fill:#fff}
.modal-bg{position:fixed;inset:0;background:rgba(var(--ov),.6);z-index:200;display:flex;align-items:flex-start;justify-content:center;padding:40px 16px;overflow:auto}
.modal{background:var(--card);border-radius:14px;max-width:760px;width:100%;box-shadow:var(--sh2);position:relative;animation:pop .2s}
.modal.lg{max-width:1000px}
.modal.sm{max-width:480px}
.modal-h{display:flex;justify-content:space-between;align-items:center;padding:14px 20px;border-bottom:1px solid var(--line);gap:12px}
.modal-h h2{margin:0;font-size:18px}
.modal-x{border:0;background:var(--bg);width:34px;height:34px;border-radius:50%;cursor:pointer;font-size:18px;flex:none}
.modal-b{padding:20px}
.modal-f{padding:12px 20px;border-top:1px solid var(--line);display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap}
@keyframes pop{from{transform:translateY(10px);opacity:0}to{transform:none;opacity:1}}
.toast-box{position:fixed;top:16px;right:16px;z-index:400;display:flex;flex-direction:column;gap:8px;max-width:360px}
.toast{background:var(--navy);color:#fff;padding:12px 16px;border-radius:10px;box-shadow:var(--sh2);font-size:14px;border-left:5px solid var(--gold);animation:pop .2s}
.toast.ok{border-left-color:#3ddc84}
.toast.err{border-left-color:#ff6b6b}
.profile{display:grid;grid-template-columns:200px 1fr;gap:22px}
.profile img{border-radius:12px;aspect-ratio:1;object-fit:cover;width:100%}
.kv{display:grid;grid-template-columns:150px 1fr;gap:6px 12px;font-size:14px}
.kv dt{color:var(--muted);font-weight:600}
.kv dd{margin:0}
.code-box{font-family:var(--fh);font-size:26px;font-weight:800;color:var(--hc);background:var(--sky);border:2px dashed var(--blue);padding:12px;border-radius:10px;text-align:center;letter-spacing:1px}
.map{width:100%;height:340px;border:0;border-radius:var(--r);background:var(--sky)}
.info-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:20px}
.info-cards>div{display:flex;gap:12px;align-items:flex-start;background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:14px}
.info-cards svg{width:30px;height:30px;stroke:var(--link);fill:none;stroke-width:1.8;flex:none}
.info-cards b{display:block;color:var(--hc)}
.info-cards span{font-size:13.5px;word-break:break-word}
.chart{width:100%;height:auto;display:block}
.chart .bar{fill:var(--blue)}
.chart .bar:hover{fill:var(--navy2)}
.chart text{font-size:11px;fill:var(--muted);font-family:var(--ff)}
.chart .val{fill:var(--ink);font-weight:600}
.chart .grid line{stroke:var(--line)}
.chart-card h3{font-size:15px;margin-bottom:4px}
.chart-tip{position:fixed;pointer-events:none;background:var(--navy);color:#fff;padding:6px 10px;border-radius:6px;font-size:12.5px;z-index:500;display:none}
.timeline{border-left:3px solid var(--sky);margin-left:8px;padding-left:20px}
.timeline .it{position:relative;margin-bottom:18px}
.timeline .it::before{content:"";position:absolute;left:-28px;top:4px;width:13px;height:13px;border-radius:50%;background:var(--gold);border:3px solid var(--card);box-shadow:0 0 0 2px var(--blue)}
.timeline .y{font-weight:800;color:var(--link);font-family:var(--fh)}
.org{display:flex;flex-direction:column;align-items:center;gap:14px}
.org .row{display:flex;gap:12px;flex-wrap:wrap;justify-content:center}
.org .n{background:var(--navy2);color:#fff;border-radius:10px;padding:10px 16px;font-weight:600;font-size:13.5px;text-align:center;min-width:150px}
.org .n.l2{background:var(--blue)}
.org .n.l3{background:var(--card);color:var(--hc);border:2px solid var(--blue)}
.org .v{width:2px;height:16px;background:var(--blue)}

/* ===== Login & Admin ===== */
.login{min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,var(--navy),var(--blue));padding:24px 16px}
.login .card{max-width:440px;width:100%;padding:28px}
.login .brand{justify-content:center;margin-bottom:12px}
.demo-users{display:grid;gap:6px;margin-top:10px}
.demo-users button{text-align:left;border:1px solid var(--line);background:var(--bg);border-radius:8px;padding:7px 10px;cursor:pointer;font-size:13px}
.demo-users button:hover{border-color:var(--link)}
.adm{display:grid;grid-template-columns:250px minmax(0,1fr);min-height:100vh;background:var(--bg2)}
.adm-side{background:var(--navy);color:rgba(255,255,255,.8);position:sticky;top:0;height:100vh;overflow:auto;display:flex;flex-direction:column}
.adm-side .brand{padding:14px 16px;color:#fff;background:rgba(0,0,0,.15)}
.adm-side .brand strong{color:#fff;font-size:18px}
.adm-side .brand small{color:rgba(255,255,255,.65)}
.adm-side .brand img{width:46px;height:46px}
.adm-side h3{font-size:11px;text-transform:uppercase;letter-spacing:1.2px;color:rgba(255,255,255,.55);margin:16px 16px 6px;font-family:var(--ff)}
.adm-side a{display:flex;align-items:center;gap:10px;padding:8px 16px;color:rgba(255,255,255,.85);text-decoration:none;font-size:14px;border-left:3px solid transparent}
.adm-side a svg{width:17px;height:17px;stroke:currentColor;fill:none;stroke-width:2;flex:none}
.adm-side a:hover{background:rgba(255,255,255,.07);color:#fff}
.adm-side a[aria-current]{background:var(--blue);color:#fff;border-left-color:var(--gold)}
.adm-side .cnt{margin-left:auto;background:var(--err);color:#fff;border-radius:999px;font-size:11px;padding:0 7px;font-weight:700}
.adm-top{background:linear-gradient(90deg,var(--navy),var(--navy2));color:#fff;display:flex;align-items:center;gap:14px;padding:10px 20px;position:sticky;top:0;z-index:40}
.adm-top .sp{flex:1}
.adm-top a,.adm-top button{color:#fff}
.adm-top .user{display:flex;align-items:center;gap:10px;font-size:13.5px;line-height:1.2}
.adm-top .user img{width:36px;height:36px;border-radius:50%;background:var(--card)}
.adm-top .user small{color:rgba(255,255,255,.7);display:block}
.adm-top .tbtn{background:rgba(255,255,255,.12);border:0;border-radius:8px;padding:7px 12px;cursor:pointer;font-size:13px;text-decoration:none;display:inline-flex;gap:6px;align-items:center}
.adm-main{padding:18px 22px 40px;min-width:0}
.adm-crumb{font-size:13px;color:var(--muted);margin-bottom:8px}
.adm-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;flex-wrap:wrap;margin-bottom:16px}
.adm-head h1{font-size:24px;margin:0;display:flex;gap:10px;align-items:center}
.adm-head p{margin:2px 0 0;color:var(--muted);font-size:14px}
.adm-head .acts{display:flex;gap:8px;flex-wrap:wrap}
.panel{background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);margin-bottom:16px}
.panel>h2{font-size:15.5px;margin:0;padding:12px 16px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:8px}
.panel .pb{padding:16px}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px;margin-bottom:16px}
.kpi{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:16px;display:flex;gap:14px;align-items:center;box-shadow:var(--sh)}
.kpi .ic{width:48px;height:48px;border-radius:12px;display:grid;place-items:center;color:#fff;flex:none}
.kpi .ic svg{width:24px;height:24px;stroke:#fff;fill:none;stroke-width:2}
.kpi b{font-family:var(--fh);font-size:26px;color:var(--hc);display:block;line-height:1.1}
.kpi span{font-size:13px;color:var(--muted)}
.edit-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:16px;align-items:start}
.row-acts{display:flex;gap:4px;flex-wrap:nowrap}
.icon-btn{border:1px solid var(--line);background:var(--card);border-radius:6px;width:30px;height:30px;display:inline-grid;place-items:center;cursor:pointer;color:var(--ink2)}
.icon-btn svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:2}
.icon-btn:hover{background:var(--sky);color:var(--link)}
.icon-btn.del:hover{background:var(--errbg);color:var(--err)}
.thumb{width:54px;height:40px;object-fit:cover;border-radius:6px;background:var(--sky)}
.avatar{width:38px;height:38px;border-radius:50%;object-fit:cover;background:var(--sky)}
.rte{border:1px solid var(--line2);border-radius:8px;background:var(--card);overflow:hidden}
.rte-bar{display:flex;flex-wrap:wrap;gap:2px;padding:6px;border-bottom:1px solid var(--line);background:var(--card2)}
.rte-bar button,.rte-bar select{border:1px solid transparent;background:none;border-radius:5px;min-width:30px;height:30px;cursor:pointer;font-weight:700;color:var(--ink2)}
.rte-bar button:hover{background:var(--sky)}
.rte-area{min-height:200px;max-height:480px;overflow:auto;padding:12px 14px;outline:none}
.rte-area:focus{background:var(--card)}
.rte-foot{font-size:12px;color:var(--muted);padding:4px 10px;text-align:right;border-top:1px solid var(--line)}
.img-field{display:flex;gap:12px;align-items:center;flex-wrap:wrap}
.img-field img{width:150px;height:96px;object-fit:cover;border-radius:8px;border:1px solid var(--line);background:var(--sky)}
.file-chip{display:inline-flex;align-items:center;gap:8px;background:var(--bg);border:1px solid var(--line);padding:6px 10px;border-radius:8px;font-size:13px;max-width:100%}
.file-chip .ft{background:#d93025;color:#fff;border-radius:4px;font-size:10px;font-weight:800;padding:2px 5px}
.meta-list{font-size:13px;color:var(--ink2);display:grid;gap:4px}
.meta-list b{color:var(--ink)}
.subtbl td,.subtbl th{padding:6px 8px;font-size:13px}
.perm-grid td,.perm-grid th{font-size:12.5px;text-align:center}
.perm-grid td:first-child,.perm-grid th:first-child{text-align:left}
.diff{font-family:ui-monospace,monospace;font-size:12px;color:var(--ink2);max-width:420px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pill-new{font-weight:700}
tr.is-new td{font-weight:600;background:var(--warnbg)!important}
tr.is-del td{opacity:.55}
.hist{font-size:13px;border-left:2px solid var(--line);padding-left:12px}
.hist div{margin-bottom:8px}
.preview-frame{border:1px solid var(--line);border-radius:var(--r);overflow:hidden}
.preview-bar{background:var(--warnbg);padding:8px 16px;font-size:13.5px;display:flex;justify-content:space-between;align-items:center;gap:10px;position:sticky;top:0;z-index:300;border-bottom:1px solid var(--warn)}

/* ===== Responsive ===== */
@media (max-width:1100px){
  .g4{grid-template-columns:repeat(2,minmax(0,1fr))}
  .h-slogan{display:none}
  .prog-facts{grid-template-columns:repeat(2,minmax(0,1fr))}
  .prog-facts>div{border-bottom:1px solid var(--line)}
  .prog-facts .cta{grid-column:1/-1}
  .site-footer .wrap{grid-template-columns:1fr 1fr}
}
@media (max-width:900px){
  .layout,.layout.left{grid-template-columns:minmax(0,1fr)}
  .layout.left aside{order:2}
  .g3{grid-template-columns:repeat(2,minmax(0,1fr))}
  .welcome{grid-template-columns:1fr}
  .welcome img{max-width:300px;margin:0 auto}
  .menu-btn{display:block}
  .h-search{display:none}
  .mainnav{position:relative}
  .mainnav>.wrap>ul{display:none;flex-direction:column}
  .mainnav.open>.wrap>ul{display:flex}
  .mainnav .sub{position:static;box-shadow:none;border-radius:0;background:rgba(255,255,255,.06);display:none}
  .mainnav li.open>.sub{display:block}
  .mainnav li:hover>.sub{display:none}
  .mainnav li.open:hover>.sub{display:block}
  .mainnav .sub a{color:rgba(255,255,255,.92)}
  .mainnav .sub a:hover{background:rgba(255,255,255,.1);color:#fff}
  .mobile-search{display:flex!important;padding:10px 16px}
  .info-cards{grid-template-columns:1fr}
  .director{grid-template-columns:1fr}
  .director img{max-height:340px;min-height:0}
  .edit-grid{grid-template-columns:minmax(0,1fr)}
  .adm{grid-template-columns:minmax(0,1fr)}
  .adm-side{position:fixed;left:-270px;width:260px;z-index:100;transition:left .2s}
  .adm-side.open{left:0}
  .adm-menu{display:inline-flex!important}
  .float-img{float:none;width:100%;margin:0 0 14px}
}
@media (max-width:640px){
  body{font-size:14.5px}
  .g2,.g3,.g4,.form-grid{grid-template-columns:minmax(0,1fr)}
  .brand img{width:50px;height:50px}
  .brand strong{font-size:20px}
  .brand small{font-size:11.5px}
  .brand em{display:none}
  .topbar .tb-links .hide-sm{display:none}
  .hero{height:400px}
  .slide .cap h2{font-size:28px}
  .slide .cap p{font-size:15px}
  .hero-arrow{display:none}
  .page-banner .ttl{font-size:28px}
  .page-banner p{font-size:15px}
  .content h1{font-size:24px}
  section.sec{padding:40px 0}
  .sec-h h2{font-size:25px}
  .quick{margin-top:-30px}
  .prog-hero .ttl{font-size:24px}
  .prog-facts{grid-template-columns:minmax(0,1fr)}
  .profile{grid-template-columns:1fr}
  .profile img{max-width:200px}
  .kv{grid-template-columns:1fr}
  .site-footer .wrap{grid-template-columns:1fr}
  .stat b{font-size:32px}
  .modal-bg{padding:12px 8px}
  .adm-main{padding:14px 12px 30px}
  .adm-top .user div{display:none}
}
.mobile-search{display:none}
.adm-menu{display:none}
@media print{
  .topbar,.site-header,.mainnav,.site-footer,.wa,.proto-ribbon,.crumbs,aside,.filters,.pager,.btn{display:none!important}
  .layout{display:block;padding:0}
}
.topbar a,.topbar span{white-space:nowrap}
@media(max-width:640px){.slide::after{background:linear-gradient(180deg,rgba(var(--ov),.55),rgba(var(--ov),.88))}}

/* =====================================================================
   DISEÑO v2 – selector de temas, animaciones y refinamiento visual
   ===================================================================== */
body{-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
::selection{background:var(--gold);color:#111}

/* Cabecera y navegación */
.topbar{background:linear-gradient(90deg,var(--navy),var(--navy2))}
.topbar .wrap{min-height:40px}
.site-header{box-shadow:0 1px 0 var(--line)}
.brand img{filter:drop-shadow(0 3px 6px rgba(var(--ov),.25));transition:transform .4s}
.brand:hover img{transform:rotate(-8deg) scale(1.04)}
.h-search{border-radius:999px;box-shadow:0 0 0 1px var(--line);overflow:hidden;background:var(--card)}
.h-search input{border:0;border-radius:0;background:transparent;color:var(--ink);padding:10px 16px}
.h-search input:focus{outline:none}
.h-search:focus-within{box-shadow:0 0 0 2px var(--blue)}
.h-search button{border-radius:0;background:var(--blue);padding:0 16px}
.h-search button svg{width:17px;height:17px;stroke:#fff;fill:none;stroke-width:2.2}
.mainnav{transition:box-shadow .2s}
.mainnav.scrolled{box-shadow:0 8px 24px rgba(var(--ov),.28)}
.mainnav .top{position:relative}
.mainnav .home svg{width:18px;height:18px;stroke:#fff;fill:none;stroke-width:2}
@media (min-width:901px){
  .mainnav .top::after{content:"";position:absolute;left:16px;right:16px;bottom:7px;height:2px;background:var(--gold);transform:scaleX(0);transition:transform .22s;transform-origin:left}
  .mainnav .top:hover::after,.mainnav li:focus-within>.top::after{transform:scaleX(1)}
  .mainnav .top.active{box-shadow:none;background:rgba(255,255,255,.12)}
  .mainnav .top.active::after{transform:scaleX(1);height:3px;bottom:0;left:0;right:0}
  .sub{border-top:3px solid var(--gold);padding:8px;border-radius:0 0 14px 14px;animation:pop .16s}
  .sub a{border-radius:8px}
  .sub a:hover{padding-left:20px}
}
.sub a{transition:.15s}
.hide-lg{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}

/* Carrusel */
.hero{height:520px}
.slide.on img{animation:kb 9s ease-out both}
@keyframes kb{from{transform:scale(1.12)}to{transform:scale(1)}}
.slide::after{background:linear-gradient(95deg,rgba(var(--ov),.94) 0%,rgba(var(--ov),.7) 42%,rgba(var(--ov),.12) 100%)}
.hero-kicker{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.25);color:#fff;border-radius:999px;padding:5px 14px 5px 10px;font-size:12.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;margin-bottom:14px;backdrop-filter:blur(4px)}
.hero-kicker svg{width:16px;height:16px;stroke:var(--gold);fill:none;stroke-width:2}
.slide .cap h2{font-size:52px;line-height:1.08;text-shadow:0 2px 18px rgba(0,0,0,.25);margin-bottom:14px}
.slide .cap p{font-size:19px;margin-bottom:22px}
.slide.on .cap .wrap>*{animation:up .7s both}
.slide.on .cap .wrap>*:nth-child(2){animation-delay:.08s}.slide.on .cap .wrap>*:nth-child(3){animation-delay:.16s}.slide.on .cap .wrap>*:nth-child(4){animation-delay:.24s}
@keyframes up{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}
.slide .btn.gold{padding:13px 24px;font-size:15px;border-radius:999px;box-shadow:0 8px 22px rgba(0,0,0,.25)}
.hero-dots button{width:10px;height:10px;transition:width .25s}
.hero-dots button[aria-current=true]{width:30px;border-radius:6px}
.hero-arrow{backdrop-filter:blur(4px);border:1px solid rgba(255,255,255,.25);width:48px;height:48px}
.btn{border-radius:10px;transition:background .15s,transform .15s,box-shadow .15s}
.btn:not(.xs):not(.sm):hover{transform:translateY(-1px);box-shadow:0 6px 16px rgba(var(--blue-rgb),.25)}
.btn.gold:hover{background:var(--gold2);color:#111}
.btn:active{transform:none}

/* Accesos rápidos */
.quick{margin-top:-58px}
.quick a{border:1px solid var(--line);border-bottom:4px solid var(--gold);padding:20px;position:relative;overflow:hidden}
.quick a::before{content:"";position:absolute;inset:auto -30px -30px auto;width:110px;height:110px;border-radius:50%;background:var(--sky);opacity:.6;transition:.3s}
.quick a:hover{transform:translateY(-5px);box-shadow:var(--sh2);border-bottom-color:var(--blue)}
.quick a:hover::before{transform:scale(1.4)}
.quick a>*{position:relative}
.quick .ic{background:linear-gradient(135deg,var(--blue),var(--navy2));box-shadow:0 6px 14px rgba(var(--blue-rgb),.35)}
.quick .ic svg{stroke:#fff}

/* Encabezados de sección */
.sec-h .kicker{display:inline-flex;align-items:center;gap:10px;color:var(--link)}
.sec-h .kicker::before,.sec-h .kicker::after{content:"";width:26px;height:2px;background:var(--gold);border-radius:2px}
.sec-h h2{font-size:36px;letter-spacing:-.4px}
.content h1::after{width:72px;background:linear-gradient(90deg,var(--gold),var(--blue))}

/* Tarjetas */
.card{transition:transform .25s,box-shadow .25s,border-color .25s}
.pcard,.ncard{border-radius:var(--r)}
.pcard img,.ncard img{transition:transform .5s}
.pcard:hover img,.ncard:hover img{transform:scale(1.06)}
.ncard .img,.pcard{overflow:hidden}
.ncard:hover{transform:translateY(-4px);box-shadow:var(--sh2)}
.pcard .more,.ncard .more{display:inline-flex;align-items:center;gap:4px;transition:gap .2s}
.pcard:hover .more,.ncard:hover .more{gap:10px}
.benefit{border-top:3px solid transparent}
.benefit:hover{transform:translateY(-4px);box-shadow:var(--sh2);border-top-color:var(--gold)}
.benefit .ic{background:linear-gradient(135deg,var(--navy2),var(--blue));box-shadow:0 6px 14px rgba(var(--blue-rgb),.3)}
.person img,.collage img,.tcard img{transition:transform .4s}
.person:hover img,.collage figure:hover img{transform:scale(1.04)}
.collage figure:hover{box-shadow:var(--sh2)}
.welcome img{border-radius:20px;box-shadow:24px 24px 0 -6px var(--sky),var(--sh2)}
.testi{position:relative}
.testi::before{content:"“";position:absolute;right:18px;top:-6px;font-family:Georgia,serif;font-size:90px;color:var(--gold);opacity:.35;line-height:1}
.event{border-left:4px solid var(--gold)}
.event:hover{transform:translateX(4px)}

/* Cifras */
.stats{position:relative;background:linear-gradient(120deg,var(--navy),var(--navy2) 55%,var(--blue));overflow:hidden}
.stats::before{content:"";position:absolute;inset:0;background-image:var(--pattern);background-size:22px 22px}
.stats .wrap{position:relative}
.stat{position:relative}
.stat+.stat::before{content:"";position:absolute;left:-9px;top:20%;bottom:20%;width:1px;background:rgba(255,255,255,.18)}
.st-ic{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;margin:0 auto 10px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2)}
.st-ic svg{width:24px;height:24px;stroke:var(--gold);fill:none;stroke-width:2}
.stat b{font-size:46px}

/* Banner interior */
.page-banner{min-height:210px}
.page-banner::after{content:"";position:absolute;inset:0;background-image:var(--pattern);background-size:20px 20px;z-index:1;mask-image:linear-gradient(90deg,#000,transparent 60%);-webkit-mask-image:linear-gradient(90deg,#000,transparent 60%)}
.page-banner .kicker{display:inline-block;background:var(--gold);color:#111;border-radius:999px;padding:3px 12px;font-size:11.5px;letter-spacing:1.2px;margin-bottom:6px}
.page-banner .ttl{font-size:44px;letter-spacing:-.5px}
.crumbs{background:var(--card2)}

/* Barra lateral y cajas */
.side-box{border-radius:var(--r)}
.side-box h2{background:linear-gradient(90deg,var(--navy2),var(--blue))}
.side-box li a{transition:.15s}
.side-box li a:hover{padding-left:20px}
.promo{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--navy2),var(--blue))}
.promo::after{content:"";position:absolute;right:-40px;bottom:-40px;width:140px;height:140px;border-radius:50%;border:18px solid rgba(255,255,255,.08)}

/* Tablas y formularios */
.tbl th{background:linear-gradient(180deg,var(--navy2),var(--navy))}
.tbl.light th{background:var(--card2);color:var(--hc);font-size:12px;text-transform:uppercase;letter-spacing:.5px}
.field input,.field select,.field textarea,.inp{border-radius:10px;transition:border-color .15s,box-shadow .15s}
.field input:focus,.field select:focus,.field textarea:focus,.inp:focus{outline:none;box-shadow:0 0 0 3px rgba(var(--blue-rgb),.2)}
.chip{transition:.15s}
.chip:hover{border-color:var(--blue)}
.modal{border-radius:18px;border:1px solid var(--line)}
.modal-h{background:var(--card2);border-radius:18px 18px 0 0}

/* Pie de página */
.site-footer{position:relative;background:linear-gradient(180deg,var(--navy2),var(--navy));border-top:4px solid var(--gold)}
.site-footer::before{content:"";position:absolute;inset:0;background-image:var(--pattern);background-size:24px 24px;opacity:.6;pointer-events:none}
.site-footer>*{position:relative}
.site-footer h2{position:relative;padding-bottom:8px}
.site-footer h2::after{content:"";position:absolute;left:0;bottom:0;width:30px;height:2px;background:var(--gold)}
.f-bottom{background:rgba(0,0,0,.18)}

/* Volver arriba */
.to-top{position:fixed;right:24px;bottom:88px;z-index:79;width:44px;height:44px;border-radius:50%;border:0;background:var(--blue);color:#fff;display:grid;place-items:center;box-shadow:var(--sh2);cursor:pointer;opacity:0;transform:translateY(12px);pointer-events:none;transition:.25s}
.to-top.show{opacity:1;transform:none;pointer-events:auto}
.to-top svg{width:20px;height:20px;stroke:#fff;fill:none;stroke-width:2.4}
.wa{animation:wa 2.8s ease-in-out infinite}
@keyframes wa{0%,100%{box-shadow:0 0 0 0 rgba(37,211,102,.45),0 6px 18px rgba(0,0,0,.25)}50%{box-shadow:0 0 0 12px rgba(37,211,102,0),0 6px 18px rgba(0,0,0,.25)}}

/* Animación de aparición */
.rv{opacity:0;transform:translateY(22px);transition:opacity .6s ease,transform .6s ease}
.rv.in{opacity:1;transform:none}

/* Panel administrativo */
.adm{background:var(--bg2)}
.adm-side{background:linear-gradient(180deg,var(--navy),var(--navy2));box-shadow:2px 0 12px rgba(var(--ov),.2)}
.adm-side nav{padding-bottom:10px}
.adm-side a{margin:1px 10px;border-radius:9px;border-left:0;padding:8px 12px;transition:.15s}
.adm-side a[aria-current]{background:rgba(255,255,255,.14);box-shadow:inset 3px 0 0 var(--gold)}
.adm-side a:hover{transform:translateX(2px)}
.adm-top{box-shadow:0 2px 12px rgba(var(--ov),.2)}
.adm-head h1{font-size:26px}
.panel{border-radius:var(--r);overflow:hidden}
.panel>h2{background:var(--card2)}
.kpi{position:relative;overflow:hidden;transition:transform .2s,box-shadow .2s}
.kpi::after{content:"";position:absolute;right:-24px;top:-24px;width:84px;height:84px;border-radius:50%;background:var(--sky);opacity:.55}
.kpi>*{position:relative;z-index:1}
a.kpi:hover{transform:translateY(-3px);box-shadow:var(--sh2)}
.kpi .ic{box-shadow:0 6px 14px rgba(0,0,0,.18)}
.kpi b{font-size:28px}
.login{background:radial-gradient(circle at 20% 20%,var(--blue2),transparent 45%),linear-gradient(135deg,var(--navy),var(--navy2))}
.login::before{content:"";position:absolute;inset:0;background-image:var(--pattern);background-size:22px 22px}
.login .card{position:relative;border-top:5px solid var(--gold);border-radius:18px;box-shadow:0 30px 60px rgba(0,0,0,.35)}
.icon-btn{border-radius:8px;transition:.15s}
.notice{border-radius:10px}

/* Modo oscuro: ajustes finos */
[data-mode="dark"] .brand img{filter:drop-shadow(0 0 10px rgba(251,191,36,.25))}
[data-mode="dark"] .tbl tbody tr:nth-child(even){background:rgba(255,255,255,.02)}
[data-mode="dark"] .badge{background:var(--sky);color:var(--link)}
[data-mode="dark"] .btn.sec{background:transparent}
[data-mode="dark"] .chart text{fill:var(--muted)}
[data-mode="dark"] .chart .val{fill:var(--ink)}
[data-mode="dark"] .f-logos a{background:var(--card2)}
[data-mode="dark"] .slide img,[data-mode="dark"] .page-banner img.bg,[data-mode="dark"] .prog-hero img{filter:brightness(.8) saturate(.9)}
[data-mode="dark"] img[src^="data:image/svg"]:not(.bg){filter:brightness(.92)}
[data-mode="dark"] .welcome img{box-shadow:24px 24px 0 -6px var(--sky),var(--sh2)}
[data-mode="dark"] .site-header{background:var(--card)}
[data-mode="dark"] .captcha b{color:var(--ink)}

@media (max-width:900px){
  .mainnav .top::after{display:none}
}
@media (max-width:640px){
  .hero{height:440px}
  .slide .cap h2{font-size:30px}
  .slide .cap p{font-size:15px}
  .sec-h h2{font-size:26px}
  .page-banner{min-height:160px}
  .page-banner .ttl{font-size:28px}
  .stat b{font-size:34px}
  .stat+.stat::before{display:none}
  .to-top{right:22px;bottom:84px}
  .quick{margin-top:-34px}
  .welcome img{box-shadow:var(--sh2)}
}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}.rv{opacity:1;transform:none}}
@media print{.rv{opacity:1!important;transform:none!important}.to-top{display:none!important}}
@media (max-width:900px){.hide-lg{position:static;width:auto;height:auto;clip:auto;overflow:visible}}
.topbar{position:relative;z-index:70}
.tbl td.num,.tbl th.num{white-space:nowrap}
.field .rte-bar select{width:auto;min-width:120px;height:30px;padding:0 8px;border:1px solid var(--line);border-radius:6px;font-weight:600}
@media (max-width:640px){.page-banner::before{background:linear-gradient(180deg,rgba(var(--ov),.6),rgba(var(--ov),.9))}}

/* ===== Pie de página v3 (ordenado) ===== */
.site-footer .wrap{display:block;padding-top:0;padding-bottom:0}
.site-footer .f-cta{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;padding-top:28px;padding-bottom:28px;border-bottom:1px solid rgba(255,255,255,.12)}
.f-cta strong{display:block;color:#fff;font-family:var(--fh);font-size:22px;line-height:1.25}
.f-cta span{color:rgba(255,255,255,.75)}
.f-cta-b{display:flex;gap:10px;flex-wrap:wrap}
.f-cta .btn{border-radius:999px;padding:11px 22px}
.btn.f-ghost{background:transparent;border-color:rgba(255,255,255,.4);color:#fff}
.btn.f-ghost:hover{background:rgba(255,255,255,.12);color:#fff}
.site-footer .f-main{display:grid;grid-template-columns:1.25fr 1fr 1.2fr 1.15fr;gap:36px;padding-top:40px;padding-bottom:36px}
.f-col h2{font-size:15px;color:#fff;margin:0 0 16px;letter-spacing:.3px}
.f-col p{color:rgba(255,255,255,.75);font-size:14px;margin:0 0 14px}
.f-brand{display:flex;gap:12px;align-items:center;margin-bottom:14px;text-decoration:none!important}
.f-brand img{width:56px;height:56px;flex:none}
.f-brand strong{color:#fff;font-family:var(--fh);font-size:20px;display:block;line-height:1.1}
.f-brand small{display:block;color:rgba(255,255,255,.7);font-size:12.5px;line-height:1.35;margin-top:2px}
.f-social{gap:8px}
.f-social a{width:36px;height:36px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);transition:.15s}
.f-social a:hover{background:var(--gold);border-color:var(--gold);transform:translateY(-2px)}
.f-social a:hover svg{fill:#111}
.f-social svg{width:16px;height:16px}
.f-links{display:grid;grid-template-columns:1fr 1fr;gap:9px 14px}
.site-footer .f-links li{margin:0}
.f-links a{display:inline-flex;align-items:flex-start;gap:6px;font-size:14px;line-height:1.35;transition:.15s}
.f-links a::before{content:"›";color:var(--gold);font-weight:700}
.f-links a:hover{color:#fff;text-decoration:none!important;transform:translateX(3px)}
.f-contact{display:grid;gap:14px}
.site-footer .f-contact li{display:flex;gap:12px;align-items:flex-start;margin:0}
.f-ic{width:36px;height:36px;border-radius:10px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.16);display:grid;place-items:center;flex:none}
.f-ic svg{width:17px;height:17px;stroke:var(--gold);fill:none;stroke-width:2}
.f-contact small{display:block;font-size:11.5px;text-transform:uppercase;letter-spacing:.8px;color:rgba(255,255,255,.55);margin-bottom:1px}
.f-contact span,.f-contact a{font-size:14px;line-height:1.4;word-break:break-word;color:rgba(255,255,255,.9)}
.site-footer .newsletter{margin:0 0 4px;border-radius:999px;overflow:hidden;background:#fff;padding:4px}
.site-footer .newsletter input{border-radius:999px;padding:8px 14px;color:#1b2433;background:#fff}
.site-footer .newsletter button{border-radius:999px;padding:8px 16px}
.f-h2b{margin-top:22px!important}
.site-footer .f-logos{margin-top:0;gap:8px}
.site-footer .f-logos a{display:inline-flex;align-items:center;gap:6px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);color:#fff;border-radius:8px;padding:7px 12px;font-size:12.5px;text-decoration:none!important;transition:.15s}
.site-footer .f-logos a:hover{background:#fff;color:var(--navy)}
.f-logos svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:2}
.f-bottom .wrap{display:flex!important;padding-top:14px!important;padding-bottom:14px!important;align-items:center}
.f-bottom span{color:rgba(255,255,255,.7)}
.f-bottom nav a{color:rgba(255,255,255,.75)}
@media (max-width:1100px){.site-footer .f-main{grid-template-columns:1fr 1fr;gap:30px}}
@media (max-width:640px){
  .site-footer .f-main{grid-template-columns:1fr;gap:28px;padding-top:30px}
  .f-cta strong{font-size:19px}
  .f-cta-b,.f-cta-b .btn{width:100%}
  .f-bottom .wrap{flex-direction:column;align-items:flex-start;gap:8px}
  .f-bottom nav{gap:6px 14px}
  .site-footer{padding-bottom:70px}
}
.site-footer .f-main{grid-template-columns:1.1fr 1.35fr 1.3fr 1.1fr}
.f-links a{white-space:nowrap}
.f-contact a,.f-contact span{overflow-wrap:anywhere;word-break:normal}
.site-footer .newsletter{display:flex;width:100%;max-width:100%}
.site-footer .newsletter input{flex:1;min-width:0;width:auto}
@media (max-width:1100px){.site-footer .f-main{grid-template-columns:1fr 1fr}}
@media (max-width:640px){.site-footer .f-main{grid-template-columns:1fr}.f-links a{white-space:normal}}
.site-footer .f-main{grid-template-columns:minmax(0,1.3fr) minmax(0,1.15fr) minmax(0,1.3fr) minmax(0,1.2fr)}
.f-links{grid-template-columns:repeat(2,minmax(0,1fr))}
.f-links a{white-space:normal}
@media (max-width:1100px){.site-footer .f-main{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:640px){.site-footer .f-main{grid-template-columns:minmax(0,1fr)}}

/* ===== Editor de texto enriquecido v2 ===== */
.rte{border-radius:12px}
.rte-bar{position:sticky;top:0;z-index:5;gap:3px;padding:8px;align-items:center}
.rte-bar button{display:inline-grid;place-items:center;min-width:32px;height:32px;border-radius:7px;font-size:15px;color:var(--ink2);transition:background .12s,color .12s}
.rte-bar button svg{width:18px;height:18px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.rte-bar button:hover{background:var(--sky);color:var(--link)}
.rte-bar button.on{background:var(--blue);color:#fff}
.rte-bar button sup,.rte-bar button sub{font-size:9px}
.field .rte-bar select{min-width:0;height:32px;background:var(--card);color:var(--ink)}
.rte-sep{width:1px;height:22px;background:var(--line2);margin:0 4px}
.rte-pop{position:relative;display:inline-flex}
.rte-menu{position:absolute;top:calc(100% + 6px);left:0;z-index:20;display:none;gap:6px;padding:8px;background:var(--card);border:1px solid var(--line);border-radius:10px;box-shadow:var(--sh2)}
.rte-menu.open{display:flex}
.rte-menu button{width:26px;height:26px;min-width:26px;border-radius:50%;border:2px solid var(--card);box-shadow:0 0 0 1px var(--line2)}
.rte-menu button:hover{transform:scale(1.12)}
.rte-menu button.auto{background:var(--card2);color:var(--ink);font-size:12px;font-weight:800}
.rte-area{min-height:260px;max-height:560px;padding:16px 20px;line-height:1.7}
.rte-area h2{font-size:24px}.rte-area h3{font-size:20px}.rte-area h4{font-size:17px}
.rte-area blockquote,.prose blockquote{border-left:4px solid var(--gold);background:var(--bg);margin:12px 0;padding:10px 16px;border-radius:0 10px 10px 0;font-style:italic;color:var(--hc)}
.rte-area table,.prose table{width:100%;border-collapse:collapse;margin:12px 0;font-size:14px}
.rte-area th,.rte-area td,.prose th,.prose td{border:1px solid var(--line2);padding:8px 10px;text-align:left;vertical-align:top}
.rte-area th,.prose th{background:var(--card2);color:var(--hc)}
.rte-area hr,.prose hr{border:0;border-top:2px solid var(--line);margin:18px 0}
.rte-area img{max-width:100%;border-radius:8px}
.rte-foot{display:flex;justify-content:space-between;gap:10px}
.rte.rte-full{position:fixed;inset:12px;z-index:350;display:flex;flex-direction:column;box-shadow:0 30px 80px rgba(0,0,0,.45)}
.rte.rte-full .rte-area{flex:1;max-height:none}
.rte.rte-full::before{content:"";position:fixed;inset:0;background:rgba(var(--ov),.55);z-index:-1}
/* Formato guardado (portal y editor) */
.al-left{text-align:left}.al-center{text-align:center}.al-right{text-align:right}.al-justify{text-align:justify;hyphens:auto}
img.al-center,.al-center>img{margin-left:auto;margin-right:auto}
.fs-sm{font-size:.85em}.fs-lg{font-size:1.25em}.fs-xl{font-size:1.6em;line-height:1.3}
.tc-blue{color:#1556b8}.tc-red{color:#c62828}.tc-green{color:#1e8e4f}.tc-gold{color:#b26b00}.tc-gray{color:#6b7686}
[data-mode="dark"] .tc-blue{color:#8ab4ff}[data-mode="dark"] .tc-red{color:#ff8a8a}[data-mode="dark"] .tc-green{color:#5fd99a}[data-mode="dark"] .tc-gold{color:#f2b23b}[data-mode="dark"] .tc-gray{color:#a7b1c4}
mark{background:#fff3a0;color:inherit;padding:0 .15em;border-radius:3px}
[data-mode="dark"] mark{background:#5c4a0b;color:#fff}
@media (max-width:640px){.rte-bar{gap:2px;padding:6px}.rte-sep{display:none}.rte-area{padding:12px}}
.rte-bar button{display:inline-flex;align-items:center;justify-content:center;padding:0 6px}

/* ===== Dashboard profesional ===== */
.db-hero{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;flex-wrap:wrap;margin:4px 0 18px}
.db-eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:1.2px;color:var(--muted);font-weight:700}
.db-hero h1{font-size:28px;margin:4px 0 2px;letter-spacing:-.3px}
.db-hero p{margin:0;color:var(--ink2)}
.db-hacts{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.db-period{display:inline-flex;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:3px}
.db-period a{padding:6px 12px;border-radius:8px;font-size:13px;font-weight:600;color:var(--ink2);text-decoration:none}
.db-period a[aria-current=true]{background:var(--blue);color:#fff}
.db-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:16px}
.db-kpi{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:16px 18px;box-shadow:var(--sh);text-decoration:none;color:inherit;display:flex;flex-direction:column;gap:10px;transition:transform .2s,box-shadow .2s,border-color .2s}
a.db-kpi:hover{transform:translateY(-3px);box-shadow:var(--sh2);border-color:var(--line2)}
.db-kh{display:flex;align-items:center;gap:10px}
.db-ki{width:34px;height:34px;border-radius:10px;background:var(--sky);display:grid;place-items:center;flex:none}
.db-ki svg{width:18px;height:18px;stroke:var(--link);fill:none;stroke-width:2}
.db-kl{font-size:13.5px;font-weight:600;color:var(--ink2)}
.db-kv{display:flex;align-items:flex-end;justify-content:space-between;gap:10px}
.db-kv b{font-family:var(--fh);font-size:32px;line-height:1;color:var(--hc);letter-spacing:-.5px}
.db-spark{width:110px;height:34px;flex:none}
.db-spark .l{fill:none;stroke:var(--blue);stroke-width:2;vector-effect:non-scaling-stroke;stroke-linejoin:round}
.db-spark .a{fill:var(--blue);opacity:.1}
.db-kf{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:12.5px;min-height:20px}
.db-delta{font-weight:700;padding:2px 7px;border-radius:999px;font-size:12px}
.db-delta.up{background:var(--okbg);color:var(--ok)}.db-delta.down{background:var(--errbg);color:var(--err)}.db-delta.eq{background:var(--graybg);color:var(--grayink)}
.db-dtxt{color:var(--muted)}
.db-dtxt.err{color:var(--err);font-weight:600}.db-dtxt.ok{color:var(--ok);font-weight:600}
.db-dtxt.sep::before{content:"·";margin-right:6px}
.db-row{display:grid;gap:16px;margin-bottom:0;align-items:start}
.db-row.r21{grid-template-columns:minmax(0,2fr) minmax(0,1fr)}
.db-row.r3{grid-template-columns:repeat(3,minmax(0,1fr))}
.db-row.r12{grid-template-columns:minmax(0,1fr) minmax(0,1.4fr)}
.db-row.r1{grid-template-columns:minmax(0,1fr)}
.db-card{height:calc(100% - 16px)}
.db-card>h2 small.db-h2s{font-family:var(--ff);font-weight:500;font-size:12.5px;color:var(--muted);margin-left:auto}
.db-lg{display:flex;gap:14px;font-family:var(--ff);font-size:12.5px;font-weight:500;color:var(--ink2)}
.db-lg span{display:inline-flex;align-items:center;gap:6px}
.db-lg i{width:18px;height:0;border-top:3px solid var(--blue);border-radius:2px}
.db-lg i.p{border-top:2px dashed var(--muted)}
.db-big{display:flex;gap:28px;flex-wrap:wrap;margin-bottom:8px}
.db-big small{display:block;color:var(--muted);font-size:12px}
.db-big b{font-family:var(--fh);font-size:22px;color:var(--hc);margin-right:8px}
.db-line svg{width:100%;height:auto;display:block}
.db-line .grid line{stroke:var(--line)}
.db-line text{font-size:11px;fill:var(--muted);font-family:var(--ff)}
.db-line .cur{fill:none;stroke:var(--blue);stroke-width:2.2;stroke-linejoin:round}
.db-line .prev{fill:none;stroke:var(--muted);stroke-width:1.5;stroke-dasharray:5 4;opacity:.7}
.db-line .area{fill:url(#dbg)}
.db-line .s1{stop-color:var(--blue);stop-opacity:.22}.db-line .s2{stop-color:var(--blue);stop-opacity:0}
.db-line .cross{stroke:var(--line2);stroke-width:1}
.db-line .dot{fill:var(--blue);stroke:var(--card);stroke-width:2.5}
.db-line .hit{fill:transparent;cursor:crosshair}
.db-note{font-size:12px;color:var(--muted);margin:6px 0 0}
.db-seg{display:flex;height:14px;border-radius:999px;overflow:hidden;gap:2px;background:var(--card);margin:4px 0 14px}
.db-seg i.warn,.db-legend .sw.warn{background:var(--warn)}.db-seg i.info,.db-legend .sw.info{background:var(--blue)}.db-seg i.ok,.db-legend .sw.ok{background:var(--ok)}.db-seg i.none{background:var(--line)}
.db-legend{list-style:none;margin:0 0 14px;padding:0;display:grid;gap:8px;font-size:13.5px}
.db-legend li{display:flex;align-items:center;gap:8px}
.db-legend .sw{width:10px;height:10px;border-radius:3px}
.db-legend b{margin-left:auto;color:var(--hc)}
.db-legend small{width:44px;text-align:right;color:var(--muted)}
.db-mini{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;border-top:1px solid var(--line);padding-top:12px}
.db-mini small{display:block;font-size:11.5px;color:var(--muted);line-height:1.3;min-height:30px}
.db-mini b{font-family:var(--fh);font-size:20px;color:var(--hc)}
.tx-err{color:var(--err)!important}
.db-tasks{list-style:none;margin:0;padding:6px 0}
.db-tasks li{display:flex;align-items:center;gap:12px;padding:9px 16px;border-bottom:1px solid var(--line)}
.db-tasks li:last-child{border-bottom:0}
.db-ti{width:32px;height:32px;border-radius:9px;display:grid;place-items:center;flex:none}
.db-ti svg{width:16px;height:16px;fill:none;stroke-width:2;stroke:currentColor}
.db-ti.violet{background:var(--violetbg);color:var(--violet)}.db-ti.warn{background:var(--warnbg);color:var(--warn)}.db-ti.err{background:var(--errbg);color:var(--err)}.db-ti.info{background:var(--infobg);color:var(--info)}.db-ti.gray{background:var(--graybg);color:var(--grayink)}
.db-tasks .l{flex:1;font-size:13.5px}
.db-tasks b{font-family:var(--fh);font-size:18px;color:var(--hc);min-width:24px;text-align:right}
.db-tasks b.z{color:var(--muted);font-weight:500}
.db-hbars{display:grid;gap:10px}
.db-hb{display:grid;grid-template-columns:minmax(0,130px) 1fr 40px;align-items:center;gap:10px;text-decoration:none;color:var(--ink);font-size:13px}
.db-hb .k{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.db-hb .t{height:10px;background:var(--bg);border-radius:999px;overflow:hidden}
.db-hb .t i{display:block;height:100%;background:var(--blue);border-radius:999px;transition:width .6s}
.db-hb b{text-align:right;color:var(--hc);font-variant-numeric:tabular-nums}
.db-hb:hover .t i{background:var(--navy2)}
.db-agenda,.db-act{list-style:none;margin:0;padding:6px 0}
.db-agenda li{display:grid;grid-template-columns:44px 1fr auto;grid-template-rows:auto auto;column-gap:12px;align-items:center;padding:9px 16px;border-bottom:1px solid var(--line)}
.db-agenda li:last-child{border-bottom:0}
.db-date{grid-row:1/3;background:var(--sky);border-radius:10px;text-align:center;padding:4px 0;line-height:1.1}
.db-date b{display:block;font-family:var(--fh);font-size:18px;color:var(--hc)}
.db-date small{font-size:10.5px;text-transform:uppercase;color:var(--link);font-weight:700}
.db-agenda a{font-size:13.5px;font-weight:600;color:var(--ink);text-decoration:none;line-height:1.3}
.db-agenda a:hover{color:var(--link)}
.db-tag{font-size:11px;font-weight:700;background:var(--graybg);color:var(--grayink);padding:2px 8px;border-radius:999px;justify-self:end}
.db-in{grid-column:2/4;color:var(--muted);font-size:12px}
.db-empty{padding:16px!important;color:var(--muted);display:block!important}
.db-health{display:flex;gap:18px;align-items:flex-start}
.db-ring{width:92px;height:92px;flex:none}
.db-ring .bg{fill:none;stroke:var(--line);stroke-width:9}
.db-ring .fg{fill:none;stroke-width:9;stroke-linecap:round}
.db-ring .fg.ok{stroke:var(--ok)}.db-ring .fg.warn{stroke:var(--warn)}.db-ring .fg.err{stroke:var(--err)}
.db-ring text{font-family:var(--fh);font-weight:800;font-size:17px;fill:var(--hc)}
.db-health ul{list-style:none;margin:0;padding:0;display:grid;gap:7px;font-size:13px;flex:1}
.db-health li{display:flex;gap:8px;align-items:flex-start}
.db-health li span{width:18px;height:18px;border-radius:50%;display:grid;place-items:center;flex:none;margin-top:1px}
.db-health li span svg{width:11px;height:11px;fill:none;stroke:#fff;stroke-width:3}
.db-health li.ok span{background:var(--ok)}.db-health li.no span{background:var(--warn)}
.db-health li.no a{color:var(--ink);font-weight:600}
.db-act li{display:flex;gap:12px;align-items:flex-start;padding:9px 16px;border-bottom:1px solid var(--line);font-size:13px}
.db-act li:last-child{border-bottom:0}
.db-act .db-av{width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,var(--blue),var(--navy2));color:#fff;font-size:11px;font-weight:800;display:grid;place-items:center;flex:none}
.db-act div{flex:1;min-width:0}
.db-act .r{color:var(--muted)}
.db-act small{color:var(--muted);text-align:right;font-size:11.5px;line-height:1.35;flex:none}
@media (max-width:1200px){.db-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.db-row.r3{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:1000px){.db-row.r21,.db-row.r12{grid-template-columns:minmax(0,1fr)}}
@media (max-width:640px){.db-kpis,.db-row.r3{grid-template-columns:minmax(0,1fr)}.db-hero h1{font-size:22px}.db-health{flex-direction:column;align-items:center}.db-mini small{min-height:0}.db-act small{display:none}}
.db-sub{font-size:13px;margin:16px 0 6px;color:var(--ink2);font-family:var(--ff);text-transform:uppercase;letter-spacing:.8px}
.db-lrl{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.db-lrl li{display:flex;align-items:center;gap:10px;justify-content:space-between;padding:8px 10px;border:1px solid var(--line);border-radius:10px}
.db-lrl a{display:flex;flex-direction:column;text-decoration:none;color:var(--ink);font-size:13px;min-width:0}
.db-lrl a b{color:var(--hc);font-size:12.5px}
.db-lrl a span{color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.db-kpis.n3{grid-template-columns:repeat(3,minmax(0,1fr))}.db-kpis.n2{grid-template-columns:repeat(2,minmax(0,1fr))}.db-kpis.n1{grid-template-columns:minmax(0,1fr)}
@media (max-width:1200px){.db-kpis.n3{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:640px){.db-kpis.n3,.db-kpis.n2{grid-template-columns:minmax(0,1fr)}}
@media (max-width:900px){.adm-top .hide-sm{display:none}.adm-top{gap:8px;padding:8px 12px}}
@media (max-width:640px){.adm-top .tbtn{font-size:0;padding:8px 9px;gap:0}.adm-top .tbtn .cnt{font-size:11px;margin-left:4px}.adm-top .user img{width:32px;height:32px}}

/* Temas y apariencia (panel) */
.tm-mock{--r2:calc(var(--r) * .6);background:var(--bg);border:1px solid var(--line);border-radius:10px;overflow:hidden;font-family:var(--ff);color:var(--ink);display:flex;flex-direction:column;height:150px;font-size:10px}
.tm-mock.big{height:auto;min-height:250px;font-size:12px}
.tm-top{height:6px;background:linear-gradient(90deg,var(--navy),var(--navy2));flex:none}
.tm-head{display:flex;align-items:center;gap:6px;background:var(--card);padding:6px 9px;border-bottom:1px solid var(--line)}
.tm-head b{font-family:var(--fh);color:var(--hc);font-size:1em;white-space:nowrap}
.tm-logo{width:14px;height:14px;border-radius:50%;background:var(--navy);box-shadow:0 0 0 2px var(--gold);flex:none}
.big .tm-logo{width:20px;height:20px}
.tm-nav{margin-left:auto;display:flex;gap:5px}
.tm-nav u{width:20px;height:4px;border-radius:3px;background:var(--line)}
.tm-nav u:first-child{background:var(--gold)}
.tm-hero{background:linear-gradient(120deg,var(--navy),var(--navy2));color:#fff;padding:12px 10px;display:flex;flex-direction:column;align-items:flex-start;gap:5px}
.big .tm-hero{padding:20px 14px}
.tm-hero b{font-family:var(--fh);font-size:1.25em;line-height:1.15}
.tm-hero small{opacity:.85}
.tm-hero em{font-style:normal;font-weight:700;background:var(--gold);color:#1b1b1b;padding:3px 9px;border-radius:var(--r2);font-size:.9em}
.tm-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(0,1fr));gap:7px;padding:8px;flex:1}
.tm-card{background:var(--card);border:1px solid var(--line);border-radius:var(--r2);padding:7px 8px;border-top:3px solid var(--gold)}
.tm-card b{display:block;font-family:var(--fh);color:var(--hc);font-size:.95em}
.tm-card p{margin:3px 0;color:var(--ink2);font-size:.9em;line-height:1.3}
.tm-mock:not(.big) .tm-card p{height:4px;background:var(--line);border-radius:3px;margin-top:6px}
.tm-card a{color:var(--link);font-weight:600;font-size:.9em}
.tm-btns{display:flex;flex-wrap:wrap;gap:6px;padding:0 8px 9px;align-items:center}
.tm-btns span{padding:4px 10px;border-radius:var(--r2);font-weight:600;font-size:.9em}
.tm-b1{background:var(--blue);color:#fff}
.tm-b2{background:var(--gold);color:#1b1b1b}
.tm-badge{background:var(--sky);color:var(--link);border-radius:999px!important}
.tm-foot{height:16px;background:var(--navy);flex:none;border-top:3px solid var(--gold)}
.tm-active .pb{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:22px;align-items:center}
.tm-active h2{margin:8px 0 4px;font-size:22px;color:var(--hc)}
.tm-active p{margin:0 0 8px;color:var(--ink2)}
.tm-meta{font-size:13px;color:var(--muted)!important}
.tm-active .badge svg{vertical-align:-2px}
.tm-chips{display:flex;flex-wrap:wrap;gap:6px;margin:6px 0 14px}
.tm-chips span{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:999px;padding:3px 10px 3px 4px;font:600 12px/1.2 ui-monospace,Menlo,Consolas,monospace;color:var(--ink2)}
.tm-chips i{width:18px;height:18px;border-radius:50%;box-shadow:inset 0 0 0 1px rgba(0,0,0,.15)}
.tm-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:16px}
.tm-item{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:10px;box-shadow:var(--sh);display:flex;flex-direction:column;transition:.15s}
.tm-item:hover{box-shadow:var(--sh2)}
.tm-item.on{border-color:var(--ok);box-shadow:0 0 0 3px var(--okbg)}
.tm-body{padding:10px 4px 2px;display:flex;flex-direction:column;flex:1}
.tm-body h3{margin:0 0 3px;font-size:15.5px;color:var(--hc);display:flex;flex-wrap:wrap;align-items:center;gap:6px}
.tm-body p{margin:0 0 10px;color:var(--muted);font-size:13px;flex:1}
.tm-acts{display:flex;flex-wrap:wrap;gap:6px}
.tm-side{position:sticky;top:76px}
.tm-cin{display:flex;gap:8px;align-items:center}
.tm-cin input[type=color]{width:46px;height:40px;padding:3px;flex:none;cursor:pointer}
.tm-hex{font-family:ui-monospace,Menlo,Consolas,monospace;text-transform:lowercase}
.tm-modo{border:0;padding:0;margin:0;display:flex;flex-wrap:wrap;gap:8px 18px;align-items:center}
.tm-modo legend{width:100%;padding:0}
.tm-modo label{display:inline-flex;align-items:center;gap:6px;font-weight:500;margin:0;cursor:pointer}
.tm-modo input{width:auto}
.field input[type=range]{padding:0;border:0;accent-color:var(--blue);outline:0;background:none}
.tm-checks{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.tm-checks li{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:8px;align-items:center;font-size:12.5px;color:var(--ink2);padding-bottom:8px;border-bottom:1px solid var(--line)}
.tm-checks li:last-child{border:0;padding:0}
.tm-checks b{font-variant-numeric:tabular-nums;color:var(--ink)}
.tm-save{display:grid;gap:8px}
@media (max-width:1100px){.tm-edit{grid-template-columns:minmax(0,1fr)}.tm-side{position:static}}
@media (max-width:760px){.tm-active .pb{grid-template-columns:minmax(0,1fr)}}
[data-mode="dark"] .btn.violet{background:#6d55d9}
.toast.warn{border-left-color:#fbbf24}

