const initials = n => n.split(" ").filter(Boolean).filter((_,i,a)=> i===0 || i===a.length-2).map(x=>x[0]).join("").slice(0,2).toUpperCase();
const kb = b => b > 1048576 ? (b/1048576).toFixed(1)+" MB" : Math.max(1,Math.round(b/1024))+" KB";
