  cols:[{h:"Programa",v:r => prog(r.prog).cod},{h:"Código",v:r => mono(r.cod)},{h:"Módulo formativo",v:r => esc(r.nombre)},{h:"Ciclos",v:r => r.ciclos},{h:"Certificados emitidos",v:r => cnt(DB.certs,c => c.mod === r.id)}],
