const optsEst = (filter) => () => DB.estudiantes.filter(filter || (() => true)).sort((a,b) => a.nom.localeCompare(b.nom)).map(e => [e.id, `${e.dni} · ${e.nom} (${prog(e.prog).cod})`]);
