};
let TC = { navy: '#0b1d3f', navy2: '#123a7a', blue: '#0a7fc2', gold: '#f5c400' };
const hexRgb = h => { h = String(h || '#000').replace('#', ''); if (h.length === 3) h = h.split('').map(c => c + c).join(''); const n = parseInt(h, 16) || 0; return [n >> 16 & 255, n >> 8 & 255, n & 255]; };
