const PALS = [['#0d3a80', '#1f6fd6'], ['#0b5d5b', '#1fa39f'], ['#6b2fa3', '#a05ce0'], ['#9a3b12', '#e0782e'], ['#14532d', '#2f9e5b'], ['#7a1f3d', '#d04772'], ['#334155', '#64748b'], ['#0f4c75', '#3282b8']];
