    case 'custom': return `<div class="field ${f.full !== false ? 'full' : ''}" data-f="${f.n}"><span class="lbl">${esc(f.l)}${req}</span><div data-custom="${f.n}">${f.render(rec)}</div>${hint}</div>`;
