    default: c = `<input id="${id}" name="${f.n}" type="${f.t || 'text'}" value="${esc(v ?? '')}" ${f.max ? `maxlength="${f.max}"` : ''} ${f.min != null ? `min="${f.min}"` : ''} ${f.step ? `step="${f.step}"` : ''} ${dis} ${f.ph ? `placeholder="${esc(f.ph)}"` : ''}>`;
