  doc.setFont('helvetica', 'bolditalic'); doc.setFontSize(7.8); doc.setTextColor(60); doc.text(`"${inst().denominacionAnio || 'Año de la Esperanza y el Fortalecimiento de la Democracia'}"`.toUpperCase(), W / 2, 31.5, { align: 'center' });
